int trig = 9;
int echo = 10;

void setup() {
    pinMode(trig, OUTPUT);
    pinMode(echo, INPUT);
    Serial.begin(9600);
}

void loop() {
    // Limpia el pin Trig
    digitalWrite(trig, LOW);
    delayMicroseconds(2);

    // Genera el pulso de 10 microsegundos
    digitalWrite(trig, HIGH);
    delayMicroseconds(10);
    digitalWrite(trig, LOW);

    // Mide la duración del pulso en Echo
    long tiempo = pulseIn(echo, HIGH);

    // Calcula la distancia en centímetros
    long distancia = tiempo / 58;

    Serial.print("Distancia: ");
    Serial.print(distancia);
    Serial.println(" cm");

    delay(500);
}
